From b8131cadc9838c141467e809e4baf2b922878d7a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:23:43 +0100
Subject: [PATCH] kded: add optional notification when Internet access is
 restored

When connectivity stayed limited long enough to show a notification, there
was nothing telling the user once the connection worked again. Send a new
event in that case, disabled by default, that can be enabled in settings.

BUG: 507593
---
 kded/connectivitymonitor.cpp    | 16 ++++++++++++++++
 kded/connectivitymonitor.h      |  2 ++
 kded/networkmanagement.notifyrc |  6 ++++++
 3 files changed, 24 insertions(+)

diff --git a/kded/connectivitymonitor.cpp b/kded/connectivitymonitor.cpp
index 0272deecb..7d838ffdd 100644
--- a/kded/connectivitymonitor.cpp
+++ b/kded/connectivitymonitor.cpp
@@ -55,6 +55,11 @@ void ConnectivityMonitor::connectivityChanged(NetworkManager::Connectivity conne
     } else {
         m_limitedConnectivityTimer.stop();

+        if (connectivity == NetworkManager::Full && m_limitedConnectivityNotified) {
+            showConnectivityRestoredNotification();
+        }
+        m_limitedConnectivityNotified = false;
+
         if (connectivity == NetworkManager::Portal) {
             qCDebug(PLASMA_NM_KDED_LOG) << "Detected captive portal";
             const NetworkManager::ActiveConnection::Ptr primaryConnection = NetworkManager::primaryConnection();
@@ -88,6 +93,8 @@ void ConnectivityMonitor::cancelLimitedConnectivityNotificationTimer()

 void ConnectivityMonitor::showLimitedConnectivityNotification()
 {
+    m_limitedConnectivityNotified = true;
+
     if (m_notification) {
         return;
     }
@@ -99,6 +106,15 @@ void ConnectivityMonitor::showLimitedConnectivityNotification()
     m_notification->sendEvent();
 }

+void ConnectivityMonitor::showConnectivityRestoredNotification()
+{
+    auto notification = new KNotification(QStringLiteral("ConnectivityRestored"));
+    notification->setComponentName(QStringLiteral("networkmanagement"));
+    notification->setTitle(i18n("Internet Access Restored"));
+    notification->setText(i18n("This device can reach the Internet again."));
+    notification->sendEvent();
+}
+
 QCoro::Task<> ConnectivityMonitor::checkConnectivity()
 {
     QDBusReply<uint> reply = co_await NetworkManager::checkConnectivity();
diff --git a/kded/connectivitymonitor.h b/kded/connectivitymonitor.h
index 8fafe4108..fb2b539eb 100644
--- a/kded/connectivitymonitor.h
+++ b/kded/connectivitymonitor.h
@@ -32,10 +32,12 @@ private Q_SLOTS:

 private:
     void showLimitedConnectivityNotification();
+    void showConnectivityRestoredNotification();

     QPointer<KNotification> m_notification;

     QTimer m_limitedConnectivityTimer;
+    bool m_limitedConnectivityNotified = false;
 };

 #endif // PLASMA_NM_CONNECTIVITY_MONITOR_H
diff --git a/kded/networkmanagement.notifyrc b/kded/networkmanagement.notifyrc
index c9ff74d9c..31591bec1 100644
--- a/kded/networkmanagement.notifyrc
+++ b/kded/networkmanagement.notifyrc
@@ -1032,6 +1032,12 @@ Urgency=Low
 IconName=network-limited
 Action=Popup

+[Event/ConnectivityRestored]
+Name=Internet Access Restored
+Urgency=Low
+IconName=network-connect
+Action=None
+
 [Event/FailedToCreateHotspot]
 Name=Failed to Create Hotspot
 Name[ar]=فشل إنشاء نقطة فعالة
